"""One actual error-operand release diagnostic after the frozen Code R3 gates."""
from pathlib import Path
from hashlib import sha256
import json,os,sys,weakref
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from tests import test_hia_machine_code_composition as controls
from hepta import hia_machine_instructions_native as instructions
base=ROOT/'development-evidence/code-literal-r3'
selectors={controls.byte_bridge.SELECTOR:str(base/'encoding/manifest.json'),
           controls.state_bridge.SELECTOR:str(base/'state/manifest.json'),
           instructions.SELECTOR:str(base/'instructions/manifest.json')}
def observation(factory):
    code=factory();events=[];references=[]
    class Temporary(list):
        def __del__(self):
            current=sys.exception()
            events.append({'event':'temporary-del','handled_type':None if current is None else type(current).__name__,
                           'handled_message':None if current is None else str(current)})
    class Mapping:
        @property
        def get(self):
            code.scratch_registers={}
            value=Temporary()
            references.append(weakref.ref(value))
            return value.append
    code.scratch_registers=Mapping()
    retained=None
    try:
        code.mov_imm('rax',17)
    except BaseException as error:
        retained=error
    if retained is None:raise AssertionError('the original two-argument builtin call must refuse')
    result={'error':{'type':type(retained).__name__,'message':str(retained),
                    'cause':None if retained.__cause__ is None else type(retained.__cause__).__name__,
                    'context':None if retained.__context__ is None else type(retained.__context__).__name__},
            'while_error_retained':{'events':list(events),'alive':[r() is not None for r in references]}}
    retained=None
    result['after_error_released']={'events':list(events),'alive':[r() is not None for r in references]}
    return result
def compare():
    wanted=observation(controls.oracle().Code)
    with controls.guarded_selection(controls.reference,controls.byte_bridge,selectors):
        actual=observation(controls.reference.Code)
    return {'expected':wanted,'actual':actual,'equal':wanted==actual}
rows=[{'outer_handler':'none',**compare()}]
try:raise LookupError('outer handler')
except LookupError:rows.append({'outer_handler':'lookup-error',**compare()})
sources=['hepta/hia_machine_state_native.py','hepta/hia_machine_instructions_native.py',
         'examples/hia_bootstrap/machine_state.hiaasm','examples/hia_bootstrap/machine_instructions.hiaasm']
report={'schema':'hepta.hia.code-error-temporary-observation.v75-r3','scope':'ACTUAL_FIXED_IMAGES_ONE_EXCEPTION_RELEASE_BOUNDARY',
        'python':sys.version,'rows':rows,'pass':all(r['equal'] for r in rows),
        'source_sha256':{p:sha256((ROOT/p).read_bytes()).hexdigest() for p in sources},
        'frozen_R3_prior_gates_unmodified':True,'new_product_revision':False}
path=ROOT/'development-evidence/code-error-temporary-r3-original.json'
assert not path.exists();path.write_text(json.dumps(report,sort_keys=True,indent=2)+'\n')
print(json.dumps(report,sort_keys=True,indent=2))
raise SystemExit(0 if report['pass'] else 1)

